// RPG: Item como POCO puro (sin MonoBehaviour)
public class Item
{
    public string id;
    public string displayName;
    public int value;
    public float weight;
    public ItemType type;
}

// Inventario como POCO con List<Item>
public class Inventory
{
    private List<Item> _items = new List<Item>();
    public int Capacity { get; }

    public bool TryAdd(Item item)
    {
        if (_items.Count >= Capacity) return false;
        _items.Add(item);
        return true;
    }

    public bool Remove(Item item) => _items.Remove(item);
}

// Stats como Dictionary para acceso rápido por nombre de stat
public class CharacterStats
{
    private Dictionary<string, int> _stats = new Dictionary<string, int>()
    {
        { "strength", 10 }, { "dexterity", 8 }, { "intelligence", 12 }
    };

    public int Get(string stat) =>
        _stats.TryGetValue(stat, out int val) ? val : 0;

    public void Modify(string stat, int delta)
    {
        if (_stats.ContainsKey(stat)) _stats[stat] += delta;
    }
}

